public static void main(Args _args)
{
    RMarketStrategyId strategyId = "DAT-STR00001";
    int actionNum = 1;

    RMarketStrategyAction action;
    RMarketSubAccount subAccount;
    boolean signal;

    action = RMarketStrategyAction::find(
        strategyId, actionNum);

    if (!action.RecId)
        throw error("Test action not found.");

    if (action.Active)
        throw error("Test action must be inactive.");

    signal = action.calcSignal(subAccount, 0);

    info(strFmt(
        "Strategy: %1, Action: %2, Signal: %3",
        action.StrategyId,
        action.Num,
        signal ? "TRUE" : "FALSE"));
}
